def describe_catalog() -> List[Dict[str, object]]:
    return list(PIPELINE_CATALOG)


def catalog_for_domain(domain: str) -> List[Dict[str, object]]:
    return [c for c in PIPELINE_CATALOG if c["domain"] == domain]

